134	  private RouterMetrics() {
135	    registry = new MetricsRegistry(RECORD_INFO);
136	    registry.tag(RECORD_INFO, "Router");
137	    getNewApplicationLatency = registry.newQuantiles("getNewApplicationLatency",
138	        "latency of get new application", "ops", "latency", 10);
139	    submitApplicationLatency = registry.newQuantiles("submitApplicationLatency",
140	        "latency of submit application", "ops", "latency", 10);
141	    killApplicationLatency = registry.newQuantiles("killApplicationLatency",
142	        "latency of kill application", "ops", "latency", 10);
143	    getApplicationReportLatency =
144	        registry.newQuantiles("getApplicationReportLatency",
145	            "latency of get application report", "ops", "latency", 10);
146	    getApplicationsReportLatency =
147	        registry.newQuantiles("getApplicationsReportLatency",
148	            "latency of get applications report", "ops", "latency", 10);
149	    getApplicationAttemptReportLatency =
150	        registry.newQuantiles("getApplicationAttemptReportLatency",
151	                    "latency of get applicationattempt " +
152	                            "report", "ops", "latency", 10);
153	    getClusterMetricsLatency =
154	        registry.newQuantiles("getClusterMetricsLatency",
155	            "latency of get cluster metrics", "ops", "latency", 10);
156	
