182	  public static RouterMetrics getMetrics() {
183	    if (!isInitialized.get()) {
184	      synchronized (RouterMetrics.class) {
185	        if (INSTANCE == null) {
186	          INSTANCE = DefaultMetricsSystem.instance().register("RouterMetrics",
187	              "Metrics for the Yarn Router", new RouterMetrics());
188	          isInitialized.set(true);
189	        }
190	      }
191	    }
192	    return INSTANCE;
193	  }
